<?php

declare(strict_types=1);

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property int $id
 * @property string $swap_request_id
 * @property string $listing_id
 * @property int $estimated_value
 */
/* @properties-end */
class SwapRequestItem extends Model
{
    public $timestamps = false;

    protected $fillable = [
        'swap_request_id', 'listing_id', 'estimated_value',
    ];

    /** @return BelongsTo<SwapRequest, $this> */
    public function swapRequest(): BelongsTo
    {
        return $this->belongsTo(SwapRequest::class);
    }

    /** @return BelongsTo<Listing, $this> */
    public function listing(): BelongsTo
    {
        return $this->belongsTo(Listing::class);
    }
}
